133	/**
134	 * Builds a 1:1 Mirror Graph from Chat History.
135	 * Every Part in history is mapped to exactly one ConcreteNode.
136	 */
137	export class ContextGraphBuilder {
138	  constructor(
139	    private readonly nodeIdentityMap: WeakMap<object, string> = new WeakMap(),
140	  ) {}
141	
142	  processHistory(history: readonly Content[]): ConcreteNode[] {
143	    const nodes: ConcreteNode[] = [];
144	
145	    // Tracks occurrences of identical turn content to ensure unique stable IDs
146	    const seenHashes = new Map<string, number>();
147	
148	    for (let turnIdx = 0; turnIdx < history.length; turnIdx++) {
149	      const msg = history[turnIdx];
150	      if (!msg.parts) continue;
151	
152	      // Defensive: Skip legacy environment header if it's the first turn.
153	      // We now manage this as an orthogonal late-addition header.
154	      if (turnIdx === 0 && msg.role === 'user' && msg.parts.length === 1) {
155	        const text = msg.parts[0].text;
156	        if (
157	          text?.startsWith('<session_context>') &&
158	          text?.includes('This is the Gemini CLI.')
159	        ) {
160	          debugLogger.log(
161	            '[ContextGraphBuilder] Skipping legacy environment header turn from graph.',
162	          );
163	          continue;
164	        }
165	      }
166	
167	      // Generate a stable salt for this turn based on its role and content
168	      const turnContent = JSON.stringify(msg.parts);
169	      const h = createHash('md5')
170	        .update(`${msg.role}:${turnContent}`)
171	        .digest('hex');
172	      const occurrence = (seenHashes.get(h) || 0) + 1;
173	      seenHashes.set(h, occurrence);
174	      const turnSalt = `${h}_${occurrence}`;
175	      const turnId = getStableId(msg, this.nodeIdentityMap, turnSalt, -1);
176	
177	      if (msg.role === 'user') {
178	        for (let partIdx = 0; partIdx < msg.parts.length; partIdx++) {
179	          const part = msg.parts[partIdx];
180	          const apiId =
181	            isFunctionResponsePart(part) &&
182	            typeof part.functionResponse.id === 'string'
183	              ? `resp_${part.functionResponse.id}_${turnSalt}_${partIdx}`
184	              : isFunctionCallPart(part) &&
185	                  typeof part.functionCall.id === 'string'
186	                ? `call_${part.functionCall.id}_${turnSalt}_${partIdx}`
187	                : undefined;
188	          const id =
189	            apiId || getStableId(part, this.nodeIdentityMap, turnSalt, partIdx);
190	          const node: ConcreteNode = {
191	            id,
192	            timestamp: Date.now(),
193	            type: isFunctionResponsePart(part)
194	              ? NodeType.TOOL_EXECUTION
195	              : NodeType.USER_PROMPT,
196	            role: 'user',
197	            payload: part,
198	            turnId,
199	          };
200	          nodes.push(node);
201	        }
202	      } else if (msg.role === 'model') {
203	        for (let partIdx = 0; partIdx < msg.parts.length; partIdx++) {
204	          const part = msg.parts[partIdx];
205	          const apiId =
206	            isFunctionCallPart(part) && typeof part.functionCall.id === 'string'
207	              ? `call_${part.functionCall.id}_${turnSalt}_${partIdx}`
208	              : undefined;
209	          const id =
210	            apiId || getStableId(part, this.nodeIdentityMap, turnSalt, partIdx);
211	          const node: ConcreteNode = {
212	            id,
213	            timestamp: Date.now(),
214	            type: isFunctionCallPart(part)
215	              ? NodeType.TOOL_EXECUTION
216	              : NodeType.AGENT_THOUGHT,
217	            role: 'model',
218	            payload: part,
219	            turnId,
220	          };
221	          nodes.push(node);
222	        }
223	      }
