7	import type { ContextWorkingBuffer, GraphMutation } from '../pipeline.js';
8	import type { ConcreteNode } from '../graph/types.js';
9	
10	export class ContextWorkingBufferImpl implements ContextWorkingBuffer {
11	  // The current active graph
12	  readonly nodes: readonly ConcreteNode[];
13	
14	  // The AOT pre-calculated provenance index (Current ID -> Pristine IDs)
15	  private readonly provenanceMap: ReadonlyMap<string, ReadonlySet<string>>;
16	
17	  // The original immutable pristine nodes mapping
18	  private readonly pristineNodesMap: ReadonlyMap<string, ConcreteNode>;
19	
20	  // The historical linked list of changes
21	  private readonly history: readonly GraphMutation[];
22	
23	  private constructor(
24	    nodes: readonly ConcreteNode[],
25	    pristineNodesMap: ReadonlyMap<string, ConcreteNode>,
26	    provenanceMap: ReadonlyMap<string, ReadonlySet<string>>,
27	    history: readonly GraphMutation[],
28	  ) {
29	    this.nodes = nodes;
30	    this.pristineNodesMap = pristineNodesMap;
31	    this.provenanceMap = provenanceMap;
32	    this.history = history;
33	  }
34	
35	  /**
36	   * Initializes a brand new ContextWorkingBuffer from a pristine graph.
37	   * Every node's provenance points to itself.
38	   */
39	  static initialize(
40	    pristineNodes: readonly ConcreteNode[],
41	  ): ContextWorkingBufferImpl {
42	    const pristineMap = new Map<string, ConcreteNode>();
43	    const initialProvenance = new Map<string, ReadonlySet<string>>();
44	
45	    for (const node of pristineNodes) {
46	      pristineMap.set(node.id, node);
47	      initialProvenance.set(node.id, new Set([node.id]));
48	    }
49	
50	    return new ContextWorkingBufferImpl(
51	      pristineNodes,
52	      pristineMap,
53	      initialProvenance,
54	      [], // Empty history
55	    );
56	  }
57	
58	  /**
59	   * Appends newly observed pristine nodes (e.g. from a user message) to the working buffer.
60	   * Ensures they are tracked in the pristine map and point to themselves in provenance.
61	   */
62	  appendPristineNodes(
63	    newNodes: readonly ConcreteNode[],
64	  ): ContextWorkingBufferImpl {
65	    if (newNodes.length === 0) return this;
66	
67	    const newPristineMap = new Map<string, ConcreteNode>(this.pristineNodesMap);
68	    const newProvenanceMap = new Map(this.provenanceMap);
69	    const existingIds = new Set(this.nodes.map((n) => n.id));
70	
71	    const nodesToAdd: ConcreteNode[] = [];
72	    const batchIds = new Set<string>();
73	    for (const node of newNodes) {
74	      if (!existingIds.has(node.id) && !batchIds.has(node.id)) {
75	        newPristineMap.set(node.id, node);
76	        newProvenanceMap.set(node.id, new Set([node.id]));
77	        nodesToAdd.push(node);
78	        batchIds.add(node.id);
79	      }
80	    }
81	
82	    if (nodesToAdd.length === 0) return this;
83	
84	    return new ContextWorkingBufferImpl(
85	      [...this.nodes, ...nodesToAdd],
86	      newPristineMap,
87	      newProvenanceMap,
88	      [...this.history],
89	    );
90	  }
91	
92	  /**
93	   * Generates an entirely new buffer instance by calculating the delta between the processor's input and output.
94	   */
95	  applyProcessorResult(
96	    processorId: string,
97	    inputTargets: readonly ConcreteNode[],
98	    outputNodes: readonly ConcreteNode[],
99	  ): ContextWorkingBufferImpl {
100	    const outputIds = new Set(outputNodes.map((n) => n.id));
101	    const inputIds = new Set(inputTargets.map((n) => n.id));
102	
103	    // Calculate diffs
104	    const removedIds = inputTargets
105	      .filter((n) => !outputIds.has(n.id))
106	      .map((n) => n.id);
107	    const addedNodes = outputNodes.filter((n) => !inputIds.has(n.id));
108	
109	    // Create mutation record
110	    const mutation: GraphMutation = {
111	      processorId,
112	      timestamp: Date.now(),
113	      removedIds,
114	      addedNodes,
115	    };
116	
117	    // Calculate new node array
118	    const removedSet = new Set(removedIds);
119	
120	    const newGraph = this.nodes.filter((n) => !removedSet.has(n.id));
121	    const insertionIndex = this.nodes.findIndex((n) => removedSet.has(n.id));
122	
123	    // IMPORTANT: We do NOT use structuredClone here.
124	    // The ContextTokenCalculator relies on a WeakMap tied to exact object references
125	    // for O(1) performance. Deep cloning would cause catastrophic cache misses.
126	    // The pipeline enforces immutability, making reference passing safe.
127	    if (insertionIndex !== -1) {
128	      newGraph.splice(insertionIndex, 0, ...addedNodes);
129	    } else {
130	      newGraph.push(...addedNodes);
131	    }
132	
133	    // Calculate new provenance map
134	    const newProvenanceMap = new Map(this.provenanceMap);
135	
136	    let finalPristineMap = this.pristineNodesMap;
137	
138	    // Map the new synthetic nodes back to their pristine roots
139	    for (const added of addedNodes) {
140	      const roots = new Set<string>();
141	
142	      // 1:1 Replacement (e.g. Masked Node)
143	      if (added.replacesId) {
144	        const inheritedRoots = this.provenanceMap.get(added.replacesId);
145	        if (inheritedRoots) {
146	          for (const rootId of inheritedRoots) roots.add(rootId);
147	        }
148	      }
149	
150	      // N:1 Abstraction (e.g. Rolling Summary)
151	      if (added.abstractsIds) {
152	        for (const abstractId of added.abstractsIds) {
153	          const inheritedRoots = this.provenanceMap.get(abstractId);
154	          if (inheritedRoots) {
155	            for (const rootId of inheritedRoots) roots.add(rootId);
156	          }
157	        }
158	      }
159	
160	      // If it has no links back to the original graph, it is its own root
161	      // (e.g., a system-injected instruction)
162	      if (roots.size === 0) {
163	        roots.add(added.id);
164	        // It acts as a net-new pristine root.
165	        if (!finalPristineMap.has(added.id)) {
166	          const mutableMap = new Map<string, ConcreteNode>(finalPristineMap);
167	          mutableMap.set(added.id, added);
168	          finalPristineMap = mutableMap;
169	        }
170	      }
171	
172	      newProvenanceMap.set(added.id, roots);
173	    }
174	
175	    // GC the Caches
176	    // We only want to keep provenance and pristine entries that are reachable
177	    // from the nodes in 'newGraph'.
178	    const reachablePristineIds = new Set<string>();
179	    const reachableCurrentIds = new Set<string>();
180	
181	    for (const node of newGraph) {
182	      reachableCurrentIds.add(node.id);
183	      const roots = newProvenanceMap.get(node.id);
184	      if (roots) {
185	        for (const root of roots) {
186	          reachablePristineIds.add(root);
187	        }
188	      }
189	    }
190	
191	    // Prune Provenance Map
192	    for (const [id] of newProvenanceMap) {
193	      if (!reachableCurrentIds.has(id)) {
194	        newProvenanceMap.delete(id);
195	      }
196	    }
197	
198	    // Prune Pristine Map
199	    const prunedPristineMap = new Map<string, ConcreteNode>();
200	    for (const id of reachablePristineIds) {
201	      const node = finalPristineMap.get(id);
202	      if (node) prunedPristineMap.set(id, node);
203	    }
204	    finalPristineMap = prunedPristineMap;
205	
206	    return new ContextWorkingBufferImpl(
207	      newGraph,
208	      finalPristineMap,
